-- C. Dense future departures: Wednesday/Friday/Sunday, through January of the following year.
SET @sgu_now=NOW(6); SET @sgu_today=CURDATE();
SET @sgu_until=STR_TO_DATE(CONCAT(YEAR(@sgu_today)+1,'-01-31'),'%Y-%m-%d');
CREATE TEMPORARY TABLE sgu_calendar_days(n INT PRIMARY KEY);
START TRANSACTION;
SELECT CONCAT('SGU-T',LPAD(t.id,2,'0'),'-',DATE_FORMAT(DATE_ADD(@sgu_today,INTERVAL days.n DAY),'%Y%m%d')),t.id,
 TIMESTAMP(DATE_ADD(@sgu_today,INTERVAL days.n DAY),'06:00:00'),
 TIMESTAMP(DATE_ADD(DATE_ADD(@sgu_today,INTERVAL days.n DAY),INTERVAL (t.duration-1) DAY),'19:30:00'),36,36,0,'OPEN'
FROM tour t CROSS JOIN sgu_calendar_days days
WHERE DATE_ADD(@sgu_today,INTERVAL days.n DAY)<=@sgu_until
 AND TIMESTAMP(DATE_ADD(@sgu_today,INTERVAL days.n DAY),'06:00:00')>@sgu_now
 AND WEEKDAY(DATE_ADD(@sgu_today,INTERVAL days.n DAY)) IN (2,4,6)
 AND NOT EXISTS(SELECT 1 FROM tour_departure d WHERE d.tour_id=t.id AND DATE(d.departure_date)=DATE_ADD(@sgu_today,INTERVAL days.n DAY))
ORDER BY days.n,t.id;
COMMIT; DROP TEMPORARY TABLE sgu_calendar_days;

