-- F. A valid long hold and an already-expired hold; no payment or mail event is fabricated.
-- The live hold is PENDING_PAYMENT: only a captured payment may assert CONFIRMED.
START TRANSACTION;
SET @sgu_departure=(SELECT id FROM tour_departure WHERE tour_id=6 AND departure_date>=TIMESTAMP(DATE_ADD(@sgu_today,INTERVAL 12 DAY),'06:00:00') AND operational_status='OPEN' AND capacity IS NOT NULL AND available_seats>=1 ORDER BY departure_date,id LIMIT 1);
SET @sgu_created=@sgu_now;
SET @sgu_booking=LAST_INSERT_ID();
UPDATE tour_departure SET available_seats=available_seats-1,version=version+1 WHERE id=@sgu_departure;
SET @sgu_deadline=(SELECT LEAST(TIMESTAMP(DATE_ADD(DATE(@sgu_created),INTERVAL 6 DAY),'08:00:00'),TIMESTAMP(DATE_SUB(DATE(departure_date),INTERVAL 6 DAY),'08:00:00')) FROM tour_departure WHERE id=@sgu_departure);
SET @sgu_reminder1=IF(TIMESTAMP(DATE_ADD(DATE(@sgu_created),INTERVAL 3 DAY),'08:00:00')<=DATE_SUB(@sgu_deadline,INTERVAL 1 DAY),TIMESTAMP(DATE_ADD(DATE(@sgu_created),INTERVAL 3 DAY),'08:00:00'),NULL);
SET @sgu_reminder2=IF(@sgu_reminder1 IS NOT NULL AND @sgu_reminder1=DATE_SUB(@sgu_deadline,INTERVAL 1 DAY),NULL,DATE_SUB(@sgu_deadline,INTERVAL 1 DAY));
SET @sgu_departure=(SELECT id FROM tour_departure WHERE tour_id=7 AND departure_date>=TIMESTAMP(DATE_ADD(@sgu_today,INTERVAL 18 DAY),'06:00:00') AND operational_status='OPEN' AND capacity IS NOT NULL AND available_seats>=1 ORDER BY departure_date,id LIMIT 1);
SET @sgu_created=DATE_SUB(@sgu_now,INTERVAL 10 DAY);
SET @sgu_booking=LAST_INSERT_ID();
SET @sgu_deadline=(SELECT LEAST(TIMESTAMP(DATE_ADD(DATE(@sgu_created),INTERVAL 6 DAY),'08:00:00'),TIMESTAMP(DATE_SUB(DATE(departure_date),INTERVAL 6 DAY),'08:00:00')) FROM tour_departure WHERE id=@sgu_departure);
SET @sgu_reminder1=IF(TIMESTAMP(DATE_ADD(DATE(@sgu_created),INTERVAL 3 DAY),'08:00:00')<=DATE_SUB(@sgu_deadline,INTERVAL 1 DAY),TIMESTAMP(DATE_ADD(DATE(@sgu_created),INTERVAL 3 DAY),'08:00:00'),NULL);
SET @sgu_reminder2=IF(@sgu_reminder1 IS NOT NULL AND @sgu_reminder1=DATE_SUB(@sgu_deadline,INTERVAL 1 DAY),NULL,DATE_SUB(@sgu_deadline,INTERVAL 1 DAY));
COMMIT;

-- Snapshot the agreed price for every booking that does not have one yet. The six preserved
-- historical bookings already carry their own snapshots above; the demo bookings below are
-- backfilled from the current tour price so the fresh database matches what the application
-- would have written at booking time (and what the migration does for an upgraded database).
   `single_supplement_price`,`total_amount`,`currency`,`snapshot_at`)
SELECT b.`id`, t.`price_id`, p.`adult_price`, p.`child_price`, p.`toddler_price`, p.`infant_price`,
       p.`single_supplement_price`,
       ROUND(COALESCE(SUM(CASE c.`booking_type`
           WHEN 'ADULT' THEN p.`adult_price`
           WHEN 'CHILD' THEN p.`child_price`
           WHEN 'TODDLER' THEN p.`toddler_price`
           WHEN 'INFANT' THEN p.`infant_price`
           ELSE 0 END), 0)),
       'VND', NOW(6)
FROM `booking` b
JOIN `tour_departure` d ON d.`id` = b.`tour_departure_id`
JOIN `tour` t ON t.`id` = d.`tour_id`
JOIN `prices` p ON p.`id` = t.`price_id`
LEFT JOIN `customer` c ON c.`booking_id` = b.`id`
LEFT JOIN `booking_price_snapshot` s ON s.`booking_id` = b.`id`
WHERE s.`booking_id` IS NULL
GROUP BY b.`id`, t.`price_id`, p.`adult_price`, p.`child_price`, p.`toddler_price`,
         p.`infant_price`, p.`single_supplement_price`;

-- G. Read-only checks after the one-time import.
SELECT 'SGU Tour ready' AS result,(SELECT COUNT(*) FROM tour) AS tours,(SELECT COUNT(*) FROM users) AS users,(SELECT COUNT(*) FROM booking) AS bookings,(SELECT COUNT(*) FROM reviews) AS reviews;
SELECT u.email,u.status,COUNT(DISTINCT b.id) AS bookings,COUNT(DISTINCT r.id) AS reviews FROM users u LEFT JOIN booking b ON b.account_id=u.id LEFT JOIN reviews r ON r.user_id=u.id WHERE u.email REGEXP '^user([1-9]|10)@gmail[.]com$' GROUP BY u.id,u.email,u.status ORDER BY u.id;
SELECT t.tour_program,DATE_FORMAT(d.departure_date,'%Y-%m') AS departure_month,COUNT(*) AS departures FROM tour t JOIN tour_departure d ON d.tour_id=t.id WHERE d.departure_date>@sgu_now GROUP BY t.id,t.tour_program,DATE_FORMAT(d.departure_date,'%Y-%m') ORDER BY t.tour_program,departure_month;
SET SESSION sql_mode=@sgu_previous_mode;
SET SESSION time_zone=@sgu_previous_timezone;
